package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Map;
import org.jsoup.SerializationException;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Attribute_setValue_TriageGen1Test {

    private Attributes parent;
    private Attribute attribute;
    private Attribute attributeWithNullValue;
    private Attribute attributeWithNullParent;

    @Before
    public void setUp() {
        parent = new Attributes();
        attribute = new Attribute("key", "oldVal", parent);
        attributeWithNullValue = new Attribute("key", null, parent);
        attributeWithNullParent = new Attribute("key", "value");
    }

    @Test
    public void testSetValue_WithNonNullParentAndExistingKey() {
        String oldValue = attribute.setValue("newValue");
        assertEquals("oldVal", oldValue);
        assertEquals("newValue", attribute.getValue());
        assertEquals("newValue", parent.get("key"));
    }

    @Test
    public void testSetValue_WithNonNullParentAndNonExistingKey() {
        parent.put("newKey", "initialValue");
        String oldValue = new Attribute("newKey", "newValue", parent).setValue("newValue");
        assertEquals("initialValue", oldValue);
        assertEquals("newValue", new Attribute("newKey", "newValue", parent).getValue());
    }

    @Test
    public void testSetValue_WithNullParent() {
        String oldValue = attributeWithNullParent.setValue("newValue");
        assertEquals("value", oldValue);
        assertEquals("newValue", attributeWithNullParent.getValue());
    }

    @Test
    public void testSetValue_WithNullKeyInParent() {
        parent.put("nullKey", null);
        Attribute attrWithNullKey = new Attribute("nullKey", "newValue", parent);
        String oldValue = attrWithNullKey.setValue("newValue");
        assertNull(oldValue);
        assertEquals("newValue", attrWithNullKey.getValue());
        assertEquals("newValue", parent.get("nullKey"));
    }

    @Test
    public void testSetValue_WithNullValue() {
        String oldValue = attribute.setValue(null);
        assertEquals("oldVal", oldValue);
        assertNull(attribute.getValue());
        assertNull(parent.get("key"));
    }

    @Test
    public void testSetValue_WithNullValueAndNullParent() {
        String oldValue = attributeWithNullParent.setValue(null);
        assertEquals("value", oldValue);
        assertNull(attributeWithNullParent.getValue());
    }

    @Test
    public void testSetValue_WithNonExistentKeyInParent() {
        String oldValue = new Attribute("nonExistentKey", "newValue", parent).setValue("newValue");
        assertNull(oldValue);
        assertEquals("newValue", new Attribute("nonExistentKey", "newValue", parent).getValue());
    }
}
